/**
 * FindOptions Operator.
 * Performs a JSONB containment (`@>`) query, matching records whose JSONB
 * column contains all the elements of the provided value. The value may be a
 * plain object, an array of objects, or an array of primitive values.
 *
 * @example
 * { someField: JsonContains({...}) }
 * { someField: JsonContains([{ id: "x" }]) }
 * { someField: JsonContains([5, 6]) }
 *
 * @param value
 */
export function JsonContains<
    T extends Record<string | number | symbol, unknown> | readonly unknown[],
>(value: T | FindOperator<T>): FindOperator<any> {
    // Arrays are serialized by the driver into the PostgreSQL array literal
    // format (e.g. "{5,6}") which is not valid JSONB. Stringifying arrays up
    // front ensures they are sent as text and coerced into jsonb by the `@>`
    // comparison. Plain objects are already serialized as JSON by the driver.
    return new FindOperator(
        "jsonContains",
        (Array.isArray(value) ? JSON.stringify(value) : value) as any,
    )
}
